#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, mod;
    cin >> n >> mod;

    auto make_tree = [&](int n) {
        int i = 2;
        while (true) {
            if (i >= n * 2) {
                vector<long long> tree(i, 0);
                return tree;
            } else {
                i *= 2;
            }
        }
    };

    auto update = [&](vector<long long>& tree, int i, long long x) {
        int size = (int)tree.size();
        i += size / 2;
        tree[i] = x;
        i /= 2;
        while (i > 0) {
            tree[i] = tree[2 * i] + tree[2 * i + 1];
            i /= 2;
        }
    };

    auto get_sum = [&](const vector<long long>& tree, int s, int t) {
        int size = (int)tree.size();
        s += size / 2;
        t += size / 2;
        long long ans = 0;
        while (s <= t) {
            if (s % 2 == 0) s /= 2;
            else {
                ans += tree[s];
                s = (s + 1) / 2;
            }
            if (t % 2 == 1) t /= 2;
            else {
                ans += tree[t];
                t = (t - 1) / 2;
            }
        }
        return ans;
    };

    auto prime_factorize = [&](long long n) {
        vector<long long> ans;
        for (long long i = 2; i * i <= n; ++i) {
            while (n % i == 0) {
                ans.push_back(i);
                n /= i;
            }
        }
        if (n != 1) ans.push_back(n);
        return ans;
    };

    auto euler_func = [&](long long n) {
        auto p = set<long long>(prime_factorize(n).begin(), prime_factorize(n).end());
        long long x = n;
        for (auto i : p) {
            x = x / i * (i - 1);
        }
        return x;
    };

    auto f = [&](long long a, long long b, int mod) {
        long long ans = 1;
        for (long long i = a; i <= b; ++i) {
            ans = (ans * i) % mod;
        }
        return ans;
    };

    long long x = euler_func(mod);
    long long l = n + 5;
    vector<long long> fact(l + 1, 1);
    for (int i = 1; i <= l; ++i) {
        fact[i] = (i * fact[i - 1]) % mod;
    }

    long long ans = 0;
    if (n > 3) {
        vector<long long> dp(2000, 0);
        dp[0] = 1; dp[1] = 2; dp[2] = 2; dp[3] = 1;

        vector<long long> tree = make_tree(2005);
        for (int i = 0; i < 4; ++i) {
            update(tree, i, dp[i]);
        }

        int m = 3;
        for (int i = 0; i <= n - 4; ++i) {
            vector<long long> dp0 = dp;
            long long ans0 = 0;
            for (int j = 0; j <= i + 3; ++j) {
                for (int k = 1; k <= m + 1; ++k) {
                    long long sum_val = get_sum(tree, j + k + 1, 2004);
                    ans0 = (ans0 + sum_val * dp0[k - 1]) % mod;
                    dp[j + k] = (dp[j + k] + dp0[k - 1]) % mod;
                    update(tree, j + k, dp[j + k]);
                }
            }
            m += i + 3;
            long long temp = f(i + 4, n, mod);
            ans = (ans + (temp * ans0) % mod) % mod;
        }
    }
    cout << ans << "\n";

    return 0;
}
